// Zet het resultaat klaar voor de workflow 'Resultaat ophalen'.
// Excel houdt maximaal 32.767 tekens per cel, en een forum met volledige
// rapporten van Digger gaat daar zo overheen. Daarom knippen we het forum
// in stukken van 30.000 en zetten die in aparte kolommen.

const bron = $input.first().json;
const trigger = $('When chat message received').first().json;

// Het beurtId komt van de pagina mee in de body. Waar de Chat Trigger dat
// precies neerzet verschilt per n8n-versie, dus we kijken op de plekken
// waar het kan staan. Blijft het leeg, dan vindt de peiling de rij nooit -
// controleer dan in de uitvoering wat de trigger werkelijk teruggeeft.
const beurtId =
  trigger.beurtId ??
  trigger.body?.beurtId ??
  trigger.query?.beurtId ??
  bron.beurtId ??
  '';

const sessionId = trigger.sessionId ?? trigger.body?.sessionId ?? bron.sessionId ?? '';

const CEL = 30000;          // ruim onder de Excel-grens van 32.767
const KOLOMMEN = 6;         // samen 180.000 tekens forum

const forumTekst = JSON.stringify(bron.forum ?? []);
const stukken = [];
for (let i = 0; i < forumTekst.length; i += CEL) {
  stukken.push(forumTekst.slice(i, i + CEL));
}

// Past het echt niet, dan liever het advies zonder overleg dan een
// afgekapte JSON die straks niet te lezen is.
if (stukken.length > KOLOMMEN) {
  stukken.length = 0;
  stukken.push('[]');
}

return [{
  json: {
    beurtId,
    sessionId,
    output: String(bron.output ?? '').slice(0, CEL),
    forum1: stukken[0] ?? '',
    forum2: stukken[1] ?? '',
    forum3: stukken[2] ?? '',
    forum4: stukken[3] ?? '',
    forum5: stukken[4] ?? '',
    forum6: stukken[5] ?? '',
    tijd: new Date().toISOString(),
  },
}];
